y_train = train['target'].values.astype(float)
X_test = test[feature_cols].values
y_test = test['target'].values

n = len(y_train)

# Implement a simple decision tree
def build_tree(X, y, max_depth=3, min_samples=2, n_features=None):
    if len(y) < min_samples or max_depth == 0 or len(np.unique(y)) == 1:
        return {'leaf': True, 'pred': int(np.round(y.mean())) if len(y) > 0 else 0}

    n_total, d = X.shape
    if n_features is None:
        feat_subset = range(d)
    else:
        feat_subset = np.random.choice(d, min(n_features, d), replace=False)

    best_gain = -1
    best_feat = 0
    best_thr = 0

    # Gini impurity
    p1 = y.mean()
    parent_gini = 2 * p1 * (1 - p1)

    for j in feat_subset:
        thresholds = np.unique(X[:, j])
        for thr in thresholds[:-1]:  # skip last
            left = y[X[:, j] <= thr]
            right = y[X[:, j] > thr]
            if len(left) < 1 or len(right) < 1:
