            gini_left = 2 * pl * (1 - pl)
            gini_right = 2 * pr * (1 - pr)
            gain = parent_gini - (len(left) * gini_left + len(right) * gini_right) / n_total
            if gain > best_gain:
                best_gain = gain
                best_feat = j
                best_thr = thr

    if best_gain <= 0:
        return {'leaf': True, 'pred': int(np.round(y.mean()))}

    left_mask = X[:, best_feat] <= best_thr
    right_mask = ~left_mask

    return {
        'leaf': False,
        'feat': best_feat,
        'thr': best_thr,
        'left': build_tree(X[left_mask], y[left_mask], max_depth-1, min_samples, n_features),
        'right': build_tree(X[right_mask], y[right_mask], max_depth-1, min_samples, n_features),
    }

